import os
from dashscope import Generation
from dashscope.api_entities.dashscope_response import DashScopeAPIResponse

def get_model_output_with_metadata(prompt: str) -> dict:
    """
    Generates text using Alibaba DashScope and returns the output along with platform metadata.

    Requires the DASHSCOPE_API_KEY environment variable to be set.

    Args:
        prompt: The input prompt for the model.

    Returns:
        A dictionary containing the model's output text and metadata from the provider.
    """
    response: DashScopeAPIResponse = Generation.call(
        model='qwen-turbo',
        prompt=prompt,
        result_format='text'
    )

    if response.status_code == 200:
        result = {
            "output": response.output.text,
            "metadata": {
                "request_id": response.request_id,
                "model_id": "qwen-turbo",
                "usage": {
                    "input_tokens": response.usage.input_tokens,
                    "output_tokens": response.usage.output_tokens,
                }
            }
        }
    else:
        result = {
            "output": None,
            "metadata": {
                "error": True,
                "request_id": response.request_id,
                "status_code": response.status_code,
                "code": response.code,
                "message": response.message,
            }
        }

    return result
